async function serveMaterialFile(req, res, material, mode = "raw") {
  const effectiveKey = material.storageKey || material.r2ObjectKey;
  if (!effectiveKey) {
    if (material.type === "notes" && material.contentText) {
      const safeFilename2 = sanitizeFileName(material.title || "note") + ".txt";
      res.setHeader("Content-Type", "text/plain; charset=utf-8");
      res.setHeader("X-Content-Type-Options", "nosniff");
      if (mode === "attachment") {
        res.setHeader(
          "Content-Disposition",
          `attachment; filename="${encodeURIComponent(safeFilename2)}"; filename*=UTF-8''${encodeURIComponent(safeFilename2)}`
        );
      } else {
        res.setHeader(
          "Content-Disposition",
          `inline; filename="${encodeURIComponent(safeFilename2)}"; filename*=UTF-8''${encodeURIComponent(safeFilename2)}`
        );
      }
      return res.send(material.contentText);
    }
    return res.status(404).json({
      error: { code: "FILE_NOT_FOUND", message: "T\xE0i li\u1EC7u n\xE0y ch\u01B0a c\xF3 t\u1EC7p \u0111\xEDnh k\xE8m." }
    });
  }
  const adapter = storageService.getAdapter(material.storageDriver);
  const exists = await adapter.exists(effectiveKey);
  if (!exists) {
    return res.status(404).json({
      error: { code: "FILE_NOT_FOUND", message: "Kh\xF4ng t\xECm th\u1EA5y t\u1EC7p tr\xEAn \u1ED5 \u0111\u0129a l\u01B0u tr\u1EEF." }
    });
  }
  const stat = await adapter.stat(effectiveKey);
  const totalSize = stat.size;
  const mimeType = material.detectedMime || material.mimeType || stat.contentType || "application/octet-stream";
  const originalName = material.originalFilename || material.fileName || material.title || "document";
  const safeFilename = sanitizeFileName(originalName);
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("Accept-Ranges", "bytes");
  res.setHeader("Content-Type", mimeType);
  if (mode === "attachment") {
    res.setHeader(
      "Content-Disposition",
      `attachment; filename="${encodeURIComponent(safeFilename)}"; filename*=UTF-8''${encodeURIComponent(safeFilename)}`
    );
  } else if (mode === "inline") {
    res.setHeader(
      "Content-Disposition",
      `inline; filename="${encodeURIComponent(safeFilename)}"; filename*=UTF-8''${encodeURIComponent(safeFilename)}`
    );
    res.setHeader("Content-Security-Policy", "default-src 'none'; style-src 'unsafe-inline'; sandbox;");
  }
  const rangeHeader = req.headers.range;
  if (rangeHeader && rangeHeader.startsWith("bytes=")) {
    const parts = rangeHeader.replace(/bytes=/, "").split("-");
    const start = parseInt(parts[0], 10);
    const end = parts[1] ? parseInt(parts[1], 10) : totalSize - 1;
    if (isNaN(start) || isNaN(end) || start >= totalSize || end >= totalSize || start > end) {
      res.setHeader("Content-Range", `bytes */${totalSize}`);
      return res.status(416).json({
        error: { code: "RANGE_NOT_SATISFIABLE", message: "Ph\u1EA1m vi y\xEAu c\u1EA7u v\u01B0\u1EE3t qu\xE1 k\xEDch th\u01B0\u1EDBc t\u1EC7p." }
      });
    }
    const chunkSize = end - start + 1;
    res.status(206);
    res.setHeader("Content-Range", `bytes ${start}-${end}/${totalSize}`);
    res.setHeader("Content-Length", chunkSize);
    const stream2 = await adapter.createReadStream(effectiveKey, { start, end });
    return stream2.pipe(res);
  }
  res.setHeader("Content-Length", totalSize);
  const stream = await adapter.createReadStream(effectiveKey);
  return stream.pipe(res);
}
