// server.ts
init_env();
init_ai_billing_service();
init_voice_session_service();
async function startServer() {
  const app = createApp();
  const PORT = env.PORT || 3e3;
  if (!isProduction && env.DEMO_LOGIN_ENABLED) {
    DemoRepository.seedUser("usr_student_demo_01");
  }
  try {
    const isConnected = await db.init();
    if (isConnected) {
      try {
        await Migrator.run();
        console.log("[JAMI AI] Schema migrations verified.");
      } catch (migErr) {
        console.error("[JAMI AI] Migration failure:", migErr.message);
        if (isProduction) {
          throw new Error(`[JAMI AI Startup] Migration failed in Production mode: ${migErr.message}`, { cause: migErr });
        }
      }
      await UserRepository.getInstance().syncWithMySQL();
      console.log("[JAMI AI] MySQL Database fully integrated and active.");
      materialWorker.start();
      aiBillingService.startReconcileQueueWorker(3e4);
      voiceSessionService.startStaleSessionSweeper(3e5);
      console.log("[JAMI AI] Background workers (MaterialWorker, ReconcileOutbox, StaleSweeper) started.");
    } else {
      if (isProduction) {
        throw new Error("[JAMI AI Startup] Failed to connect to MySQL database in Production mode.");
      }
      console.warn("[JAMI AI] Running in standalone demo mode.");
    }
  } catch (err) {
    console.error("[JAMI AI] MySQL initialization error:", err.message);
    if (isProduction) {
      process.exit(1);
    }
  }
  if (!isProduction) {
    const vite = await (0, import_vite.createServer)({
      server: { middlewareMode: true },
      appType: "spa"
    });
    app.use(vite.middlewares);
  } else {
    let distPath = import_path7.default.join(process.cwd(), "dist", "client");
    if (!import_fs6.default.existsSync(distPath)) {
      distPath = import_path7.default.join(process.cwd(), "dist");
    }
    app.use("/assets", import_express3.default.static(import_path7.default.join(distPath, "assets"), {
      maxAge: "1y",
      immutable: true
    }));
    app.use(import_express3.default.static(distPath, {
      setHeaders: (res, filePath) => {
        if (filePath.endsWith(".html")) {
          res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate");
        }
      }
    }));
    app.get("/assets/*", (_req, res) => {
      res.status(404).send("Asset not found");
    });
    app.get("*", (_req, res) => {
      res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate");
      res.sendFile(import_path7.default.join(distPath, "index.html"));
    });
  }
  app.listen(PORT, "0.0.0.0", () => {
    console.log(`[JAMI AI] Server running on http://0.0.0.0:${PORT} (Mode: ${env.APP_MODE}, Demo: ${env.DEMO_LOGIN_ENABLED})`);
  });
}
startServer();
